package com.bank.dsa;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

// Runnable demo: largest transaction amount of the day (single pass).
public class LargestOfNDemo {
    private static final Logger log = Logger.getLogger(LargestOfNDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        MaxFinder finder = new MaxFinder();

        List<BigDecimal> amounts = List.of(
                new BigDecimal("3"), new BigDecimal("9"), new BigDecimal("2"),
                new BigDecimal("15"), new BigDecimal("7"));   // N = 5 values
        BigDecimal largest = finder.largest(amounts);
        log.info(() -> "Largest transaction of the day = Rs." + largest);
    }
}

// ─── Would be in MaxFinder.java in a real project ───
class MaxFinder {
    // Seed max with the FIRST value (not 0), then scan the rest. compareTo for money.
    BigDecimal largest(List<BigDecimal> amounts) {
        if (amounts == null || amounts.isEmpty()) {
            throw new IllegalArgumentException("Need at least one amount");
        }
        BigDecimal max = amounts.get(0);            // read first into max
        for (int i = 1; i < amounts.size(); i++) {  // i = 2..N (0-based 1..size-1)
            BigDecimal x = amounts.get(i);
            if (x.compareTo(max) > 0) {             // x > max ?
                max = x;                            // update running maximum
            }
        }
        return max;
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
